-- =====================================================
-- STEP 2: System placeholder VDs (NEVER deactivate)
-- =====================================================
CREATE TEMP TABLE tmp_system_vds (vd_code VARCHAR(20));
INSERT INTO tmp_system_vds VALUES
('0'), ('00000000'), ('11111111'), ('22222222'), ('33333333'), ('99999999');

-- =====================================================
-- STEP 3: Pre-migration report
-- =====================================================

-- VDs NOT in VSListing that HAVE members (will NOT be deactivated)
SELECT
    'SKIPPED - has members' AS action,
    vd.voting_district_code,
    vd.voting_district_name,
    vd.ward_code,
    COUNT(mc.member_id) AS member_count
FROM voting_districts vd
LEFT JOIN members_consolidated mc ON vd.voting_district_code = mc.voting_district_code
WHERE (vd.is_active = TRUE OR vd.is_active IS NULL)
AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_spreadsheet_vds)
AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_system_vds)
GROUP BY vd.voting_district_code, vd.voting_district_name, vd.ward_code
HAVING COUNT(mc.member_id) > 0
ORDER BY COUNT(mc.member_id) DESC;

-- VDs to be deactivated (0 members, not system, not in VSListing)
SELECT
    'WILL DEACTIVATE' AS action,
    COUNT(*) AS count
FROM voting_districts vd
LEFT JOIN members_consolidated mc ON vd.voting_district_code = mc.voting_district_code
WHERE (vd.is_active = TRUE OR vd.is_active IS NULL)
AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_spreadsheet_vds)
AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_system_vds)
GROUP BY vd.voting_district_code
HAVING COUNT(mc.member_id) = 0;

-- =====================================================
-- STEP 4: Create audit log
-- =====================================================
CREATE TABLE IF NOT EXISTS vd_deactivation_audit_log (
    audit_id SERIAL PRIMARY KEY,
    voting_district_code VARCHAR(20) NOT NULL,
    voting_district_name TEXT,
    ward_code VARCHAR(20),
    member_count INTEGER DEFAULT 0,
    reason TEXT,
    deactivated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- =====================================================
-- STEP 5: Log and deactivate
-- =====================================================

-- Log VDs being deactivated
INSERT INTO vd_deactivation_audit_log (voting_district_code, voting_district_name, ward_code, member_count, reason)
SELECT
    vd.voting_district_code,
    vd.voting_district_name,
    vd.ward_code,
    0,
    'Not in VSListing_20260601 - decommissioned voting station (0 members)'
FROM voting_districts vd
LEFT JOIN members_consolidated mc ON vd.voting_district_code = mc.voting_district_code
WHERE (vd.is_active = TRUE OR vd.is_active IS NULL)
AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_spreadsheet_vds)
AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_system_vds)
GROUP BY vd.voting_district_code, vd.voting_district_name, vd.ward_code
HAVING COUNT(mc.member_id) = 0;

-- Deactivate them
UPDATE voting_districts
SET is_active = FALSE
WHERE voting_district_code IN (
    SELECT vd.voting_district_code
    FROM voting_districts vd
    LEFT JOIN members_consolidated mc ON vd.voting_district_code = mc.voting_district_code
    WHERE (vd.is_active = TRUE OR vd.is_active IS NULL)
    AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_spreadsheet_vds)
    AND vd.voting_district_code NOT IN (SELECT vd_code FROM tmp_system_vds)
    GROUP BY vd.voting_district_code
    HAVING COUNT(mc.member_id) = 0
);

-- =====================================================
-- STEP 6: Post-migration summary
-- =====================================================
DO $$
DECLARE
    deactivated INTEGER;
    remaining_active INTEGER;
BEGIN
    SELECT COUNT(*) INTO deactivated
    FROM vd_deactivation_audit_log
    WHERE deactivated_at >= CURRENT_DATE;

    SELECT COUNT(*) INTO remaining_active
    FROM voting_districts
    WHERE is_active = TRUE OR is_active IS NULL;

    RAISE NOTICE 'Deactivated % redundant VDs with 0 members', deactivated;
    RAISE NOTICE 'Remaining active VDs in DB: %', remaining_active;
END $$;

SELECT
    'Deactivation Summary' AS report,
    (SELECT COUNT(*) FROM vd_deactivation_audit_log WHERE deactivated_at >= CURRENT_DATE) AS vds_deactivated,
    (SELECT COUNT(*) FROM voting_districts WHERE is_active = TRUE OR is_active IS NULL) AS remaining_active_vds;

-- =====================================================
-- STEP 7: Refresh materialized views
-- =====================================================
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_voting_district_compliance;
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_ward_compliance_summary;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = 'mv_membership_analytics_summary') THEN
        REFRESH MATERIALIZED VIEW CONCURRENTLY mv_membership_analytics_summary;
        RAISE NOTICE 'Refreshed mv_membership_analytics_summary';
    END IF;
END $$;

-- Cleanup
DROP TABLE IF EXISTS tmp_spreadsheet_vds;
DROP TABLE IF EXISTS tmp_system_vds;

COMMIT;

SELECT 'REDUNDANT VD DEACTIVATION COMPLETE' AS status;